" 85 :   void add(Node n, Context context) {
 86 :     if (!cc.continueProcessing()) {
 87 :       return;
 88 :     }
 89 : 
 90 :     int type = n.getType();
 91 :     String opstr = NodeUtil.opToStr(type);
 92 :     int childCount = n.getChildCount();
 93 :     Node first = n.getFirstChild();
 94 :     Node last = n.getLastChild();
 95 : 
 96 :     // Handle all binary operators
 97 :     if (opstr != null && first != last) {
 98 :       Preconditions.checkState(
 99 :           childCount == 2,
100 :           "Bad binary operator \"%s\": expected 2 arguments but got %s",
101 :           opstr, childCount);
102 :       int p = NodeUtil.precedence(type);
103 :       addExpr(first, p, context);
104 :       cc.addOp(opstr, true);
105 : 
106 :       // For right-hand-side of operations, only pass context if it's
107 :       // the IN_FOR_INIT_CLAUSE one.
108 :       Context rhsContext = getContextForNoInOperator(context);
109 : 
110 :       // Handle associativity.
111 :       // e.g. if the parse tree is a * (b * c),
112 :       // we can simply generate a * b * c.
113 :       if (last.getType() == type &&
114 :           NodeUtil.isAssociative(type)) {
115 :         addExpr(last, p, rhsContext);
116 :       } else if (NodeUtil.isAssignmentOp(n) && NodeUtil.isAssignmentOp(last)) {
117 :         // Assignments are the only right-associative binary operators
118 :         addExpr(last, p, rhsContext);
119 :       } else {
120 :         addExpr(last, p + 1, rhsContext);
121 :       }
122 :       return;
123 :     }
124 : 
125 :     cc.startSourceMapping(n);
126 : 
127 :     switch (type) {
128 :       case Token.TRY: {
129 :         Preconditions.checkState(first.getNext().isBlock() &&
130 :                 !first.getNext().hasMoreThanOneChild());
131 :         Preconditions.checkState(childCount >= 2 && childCount <= 3);
132 : 
133 :         add("try");
134 :         add(first, Context.PRESERVE_BLOCK);
135 : 
136 :         // second child contains the catch block, or nothing if there
137 :         // isn't a catch block
138 :         Node catchblock = first.getNext().getFirstChild();
139 :         if (catchblock != null) {
140 :           add(catchblock);
141 :         }
142 : 
143 :         if (childCount == 3) {
144 :           add("finally");
145 :           add(last, Context.PRESERVE_BLOCK);
146 :         }
147 :         break;
148 :       }
149 : 
150 :       case Token.CATCH:
151 :         Preconditions.checkState(childCount == 2);
152 :         add("catch(");
153 :         add(first);
154 :         add(")");
155 :         add(last, Context.PRESERVE_BLOCK);
156 :         break;
157 : 
158 :       case Token.THROW:
159 :         Preconditions.checkState(childCount == 1);
160 :         add("throw");
161 :         add(first);
162 : 
163 :         // Must have a ';' after a throw statement, otherwise safari can't
164 :         // parse this.
165 :         cc.endStatement(true);
166 :         break;
167 : 
168 :       case Token.RETURN:
169 :         add("return");
170 :         if (childCount == 1) {
171 :           add(first);
172 :         } else {
173 :           Preconditions.checkState(childCount == 0);
174 :         }
175 :         cc.endStatement();
176 :         break;
177 : 
178 :       case Token.VAR:
179 :         if (first != null) {
180 :           add("var ");
181 :           addList(first, false, getContextForNoInOperator(context));
182 :         }
183 :         break;
184 : 
185 :       case Token.LABEL_NAME:
186 :         Preconditions.checkState(!n.getString().isEmpty());
187 :         addIdentifier(n.getString());
188 :         break;
189 : 
190 :       case Token.NAME:
191 :         if (first == null || first.isEmpty()) {
192 :           addIdentifier(n.getString());
193 :         } else {
194 :           Preconditions.checkState(childCount == 1);
195 :           addIdentifier(n.getString());
196 :           cc.addOp("=", true);
197 :           if (first.isComma()) {
198 :             addExpr(first, NodeUtil.precedence(Token.ASSIGN), Context.OTHER);
199 :           } else {
200 :             // Add expression, consider nearby code at lowest level of
201 :             // precedence.
202 :             addExpr(first, 0, getContextForNoInOperator(context));
203 :           }
204 :         }
205 :         break;
206 : 
207 :       case Token.ARRAYLIT:
208 :         add("[");
209 :         addArrayList(first);
210 :         add("]");
211 :         break;
212 : 
213 :       case Token.PARAM_LIST:
214 :         add("(");
215 :         addList(first);
216 :         add(")");
217 :         break;
218 : 
219 :       case Token.COMMA:
220 :         Preconditions.checkState(childCount == 2);
221 : 
222 :         // We could use addList recursively here, but sometimes we produce
223 :         // very deeply nested commas and run out of stack space, so we
224 :         // just unroll the recursion.
225 :         //
226 :         // We assume COMMA nodes are left-recursive.
227 :         Node firstNonComma = n.getFirstChild();
228 :         while (firstNonComma.getType() == Token.COMMA) {
229 :           firstNonComma = firstNonComma.getFirstChild();
230 :         }
231 : 
232 :         addExpr(firstNonComma, 0, context);
233 : 
234 :         Node current = firstNonComma;
235 :         do {
236 :           current = current.getParent();
237 :           cc.listSeparator();
238 :           addExpr(current.getFirstChild().getNext(), 0, Context.OTHER);
239 :         } while (current != n);
240 : 
241 :         break;
242 : 
243 :       case Token.NUMBER:
244 :         Preconditions.checkState(childCount == 0);
245 :         cc.addNumber(n.getDouble());
246 :         break;
247 : 
248 :       case Token.TYPEOF:
249 :       case Token.VOID:
250 :       case Token.NOT:
251 :       case Token.BITNOT:
252 :       case Token.POS: {
253 :         // All of these unary operators are right-associative
254 :         Preconditions.checkState(childCount == 1);
255 :         cc.addOp(NodeUtil.opToStrNoFail(type), false);
256 :         addExpr(first, NodeUtil.precedence(type), Context.OTHER);
257 :         break;
258 :       }
259 : 
260 :       case Token.NEG: {
261 :         Preconditions.checkState(childCount == 1);
262 : 
263 :         // It's important to our sanity checker that the code
264 :         // we print produces the same AST as the code we parse back.
265 :         // NEG is a weird case because Rhino parses "- -2" as "2".
266 :         if (n.getFirstChild().isNumber()) {
267 :           cc.addNumber(-n.getFirstChild().getDouble());
268 :         } else {
269 :           cc.addOp(NodeUtil.opToStrNoFail(type), false);
270 :           addExpr(first, NodeUtil.precedence(type), Context.OTHER);
271 :         }
272 : 
273 :         break;
274 :       }
275 : 
276 :       case Token.HOOK: {
277 :         Preconditions.checkState(childCount == 3);
278 :         int p = NodeUtil.precedence(type);
279 :         addExpr(first, p + 1, context);
280 :         cc.addOp("?", true);
281 :         addExpr(first.getNext(), 1, Context.OTHER);
282 :         cc.addOp(":", true);
283 :         addExpr(last, 1, Context.OTHER);
284 :         break;
285 :       }
286 : 
287 :       case Token.REGEXP:
288 :         if (!first.isString() ||
289 :             !last.isString()) {
290 :           throw new Error("Expected children to be strings");
291 :         }
292 : 
293 :         String regexp = regexpEscape(first.getString(), outputCharsetEncoder);
294 : 
295 :         // I only use one .add because whitespace matters
296 :         if (childCount == 2) {
297 :           add(regexp + last.getString());
298 :         } else {
299 :           Preconditions.checkState(childCount == 1);
300 :           add(regexp);
301 :         }
302 :         break;
303 : 
304 :       case Token.FUNCTION:
305 :         if (n.getClass() != Node.class) {
306 :           throw new Error("Unexpected Node subclass.");
307 :         }
308 :         Preconditions.checkState(childCount == 3);
309 :         boolean funcNeedsParens = (context == Context.START_OF_EXPR);
310 :         if (funcNeedsParens) {
311 :           add("(");
312 :         }
313 : 
314 :         add("function");
315 :         add(first);
316 : 
317 :         add(first.getNext());
318 :         add(last, Context.PRESERVE_BLOCK);
319 :         cc.endFunction(context == Context.STATEMENT);
320 : 
321 :         if (funcNeedsParens) {
322 :           add(")");
323 :         }
324 :         break;
325 : 
326 :       case Token.GETTER_DEF:
327 :       case Token.SETTER_DEF:
328 :         Preconditions.checkState(n.getParent().isObjectLit());
329 :         Preconditions.checkState(childCount == 1);
330 :         Preconditions.checkState(first.isFunction());
331 : 
332 :         // Get methods are unnamed
333 :         Preconditions.checkState(first.getFirstChild().getString().isEmpty());
334 :         if (type == Token.GETTER_DEF) {
335 :           // Get methods have no parameters.
336 :           Preconditions.checkState(!first.getChildAtIndex(1).hasChildren());
337 :           add("get ");
338 :         } else {
339 :           // Set methods have one parameter.
340 :           Preconditions.checkState(first.getChildAtIndex(1).hasOneChild());
341 :           add("set ");
342 :         }
343 : 
344 :         // The name is on the GET or SET node.
345 :         String name = n.getString();
346 :         Node fn = first;
347 :         Node parameters = fn.getChildAtIndex(1);
348 :         Node body = fn.getLastChild();
349 : 
350 :         // Add the property name.
351 :         if (!n.isQuotedString() &&
352 :             TokenStream.isJSIdentifier(name) &&
353 :             // do not encode literally any non-literal characters that were
354 :             // unicode escaped.
355 :             NodeUtil.isLatin(name)) {
356 :           add(name);
357 :         } else {
358 :           // Determine if the string is a simple number.
359 :           double d = getSimpleNumber(name);
360 :           if (!Double.isNaN(d)) {
361 :             cc.addNumber(d);
362 :           } else {
363 :             addJsString(n);
364 :           }
365 :         }
366 : 
367 :         add(parameters);
368 :         add(body, Context.PRESERVE_BLOCK);
369 :         break;
370 : 
371 :       case Token.SCRIPT:
372 :       case Token.BLOCK: {
373 :         if (n.getClass() != Node.class) {
374 :           throw new Error("Unexpected Node subclass.");
375 :         }
376 :         boolean preserveBlock = context == Context.PRESERVE_BLOCK;
377 :         if (preserveBlock) {
378 :           cc.beginBlock();
379 :         }
380 : 
381 :         boolean preferLineBreaks =
382 :             type == Token.SCRIPT ||
383 :             (type == Token.BLOCK &&
384 :                 !preserveBlock &&
385 :                 n.getParent() != null &&
386 :                 n.getParent().isScript());
387 :         for (Node c = first; c != null; c = c.getNext()) {
388 :           add(c, Context.STATEMENT);
389 : 
390 :           // VAR doesn't include ';' since it gets used in expressions
391 :           if (c.isVar()) {
392 :             cc.endStatement();
393 :           }
394 : 
395 :           if (c.isFunction()) {
396 :             cc.maybeLineBreak();
397 :           }
398 : 
399 :           // Prefer to break lines in between top-level statements
400 :           // because top level statements are more homogeneous.
401 :           if (preferLineBreaks) {
402 :             cc.notePreferredLineBreak();
403 :           }
404 :         }
405 :         if (preserveBlock) {
406 :           cc.endBlock(cc.breakAfterBlockFor(n, context == Context.STATEMENT));
407 :         }
408 :         break;
409 :       }
410 : 
411 :       case Token.FOR:
412 :         if (childCount == 4) {
413 :           add("for(");
414 :           if (first.isVar()) {
415 :             add(first, Context.IN_FOR_INIT_CLAUSE);
416 :           } else {
417 :             addExpr(first, 0, Context.IN_FOR_INIT_CLAUSE);
418 :           }
419 :           add(";");
420 :           add(first.getNext());
421 :           add(";");
422 :           add(first.getNext().getNext());
423 :           add(")");
424 :           addNonEmptyStatement(
425 :               last, getContextForNonEmptyExpression(context), false);
426 :         } else {
427 :           Preconditions.checkState(childCount == 3);
428 :           add("for(");
429 :           add(first);
430 :           add("in");
431 :           add(first.getNext());
432 :           add(")");
433 :           addNonEmptyStatement(
434 :               last, getContextForNonEmptyExpression(context), false);
435 :         }
436 :         break;
437 : 
438 :       case Token.DO:
439 :         Preconditions.checkState(childCount == 2);
440 :         add("do");
441 :         addNonEmptyStatement(first, Context.OTHER, false);
442 :         add("while(");
443 :         add(last);
444 :         add(")");
445 :         cc.endStatement();
446 :         break;
447 : 
448 :       case Token.WHILE:
449 :         Preconditions.checkState(childCount == 2);
450 :         add("while(");
451 :         add(first);
452 :         add(")");
453 :         addNonEmptyStatement(
454 :             last, getContextForNonEmptyExpression(context), false);
455 :         break;
456 : 
457 :       case Token.EMPTY:
458 :         Preconditions.checkState(childCount == 0);
459 :         break;
460 : 
461 :       case Token.GETPROP: {
462 :         Preconditions.checkState(
463 :             childCount == 2,
464 :             "Bad GETPROP: expected 2 children, but got %s", childCount);
465 :         Preconditions.checkState(
466 :             last.isString(),
467 :             "Bad GETPROP: RHS should be STRING");
468 :         boolean needsParens = (first.isNumber());
469 :         if (needsParens) {
470 :           add("(");
471 :         }
472 :         addExpr(first, NodeUtil.precedence(type), context);
473 :         if (needsParens) {
474 :           add(")");
475 :         }
476 :         add(".");
477 :         addIdentifier(last.getString());
478 :         break;
479 :       }
480 : 
481 :       case Token.GETELEM:
482 :         Preconditions.checkState(
483 :             childCount == 2,
484 :             "Bad GETELEM: expected 2 children but got %s", childCount);
485 :         addExpr(first, NodeUtil.precedence(type), context);
486 :         add("[");
487 :         add(first.getNext());
488 :         add("]");
489 :         break;
490 : 
491 :       case Token.WITH:
492 :         Preconditions.checkState(childCount == 2);
493 :         add("with(");
494 :         add(first);
495 :         add(")");
496 :         addNonEmptyStatement(
497 :             last, getContextForNonEmptyExpression(context), false);
498 :         break;
499 : 
500 :       case Token.INC:
501 :       case Token.DEC: {
502 :         Preconditions.checkState(childCount == 1);
503 :         String o = type == Token.INC ? "++" : "--";
504 :         int postProp = n.getIntProp(Node.INCRDECR_PROP);
505 :         // A non-zero post-prop value indicates a post inc/dec, default of zero
506 :         // is a pre-inc/dec.
507 :         if (postProp != 0) {
508 :           addExpr(first, NodeUtil.precedence(type), context);
509 :           cc.addOp(o, false);
510 :         } else {
511 :           cc.addOp(o, false);
512 :           add(first);
513 :         }
514 :         break;
515 :       }
516 : 
517 :       case Token.CALL:
518 :         // We have two special cases here:
519 :         // 1) If the left hand side of the call is a direct reference to eval,
520 :         // then it must have a DIRECT_EVAL annotation. If it does not, then
521 :         // that means it was originally an indirect call to eval, and that
522 :         // indirectness must be preserved.
523 :         // 2) If the left hand side of the call is a property reference,
524 :         // then the call must not a FREE_CALL annotation. If it does, then
525 :         // that means it was originally an call without an explicit this and
526 :         // that must be preserved.
527 :         if (isIndirectEval(first)
528 :             || n.getBooleanProp(Node.FREE_CALL) && NodeUtil.isGet(first)) {
529 :           add("(0,");
530 :           addExpr(first, NodeUtil.precedence(Token.COMMA), Context.OTHER);
531 :           add(")");
532 :         } else {
533 :           addExpr(first, NodeUtil.precedence(type), context);
534 :         }
535 :         add("(");
536 :         addList(first.getNext());
537 :         add(")");
538 :         break;
539 : 
540 :       case Token.IF:
541 :         boolean hasElse = childCount == 3;
542 :         boolean ambiguousElseClause =
543 :             context == Context.BEFORE_DANGLING_ELSE && !hasElse;
544 :         if (ambiguousElseClause) {
545 :           cc.beginBlock();
546 :         }
547 : 
548 :         add("if(");
549 :         add(first);
550 :         add(")");
551 : 
552 :         if (hasElse) {
553 :           addNonEmptyStatement(
554 :               first.getNext(), Context.BEFORE_DANGLING_ELSE, false);
555 :           add("else");
556 :           addNonEmptyStatement(
557 :               last, getContextForNonEmptyExpression(context), false);
558 :         } else {
559 :           addNonEmptyStatement(first.getNext(), Context.OTHER, false);
560 :           Preconditions.checkState(childCount == 2);
561 :         }
562 : 
563 :         if (ambiguousElseClause) {
564 :           cc.endBlock();
565 :         }
566 :         break;
567 : 
568 :       case Token.NULL:
569 :         Preconditions.checkState(childCount == 0);
570 :         add("null");
571 :         break;
572 : 
573 :       case Token.THIS:
574 :         Preconditions.checkState(childCount == 0);
575 :         add("this");
576 :         break;
577 : 
578 :       case Token.FALSE:
579 :         Preconditions.checkState(childCount == 0);
580 :         add("false");
581 :         break;
582 : 
583 :       case Token.TRUE:
584 :         Preconditions.checkState(childCount == 0);
585 :         add("true");
586 :         break;
587 : 
588 :       case Token.CONTINUE:
589 :         Preconditions.checkState(childCount <= 1);
590 :         add("continue");
591 :         if (childCount == 1) {
592 :           if (!first.isLabelName()) {
593 :             throw new Error("Unexpected token type. Should be LABEL_NAME.");
594 :           }
595 :           add(" ");
596 :           add(first);
597 :         }
598 :         cc.endStatement();
599 :         break;
600 : 
601 :       case Token.DEBUGGER:
602 :         Preconditions.checkState(childCount == 0);
603 :         add("debugger");
604 :         cc.endStatement();
605 :         break;
606 : 
607 :       case Token.BREAK:
608 :         Preconditions.checkState(childCount <= 1);
609 :         add("break");
610 :         if (childCount == 1) {
611 :           if (!first.isLabelName()) {
612 :             throw new Error("Unexpected token type. Should be LABEL_NAME.");
613 :           }
614 :           add(" ");
615 :           add(first);
616 :         }
617 :         cc.endStatement();
618 :         break;
619 : 
620 :       case Token.EXPR_RESULT:
621 :         Preconditions.checkState(childCount == 1);
622 :         add(first, Context.START_OF_EXPR);
623 :         cc.endStatement();
624 :         break;
625 : 
626 :       case Token.NEW:
627 :         add("new ");
628 :         int precedence = NodeUtil.precedence(type);
629 : 
630 :         // If the first child contains a CALL, then claim higher precedence
631 :         // to force parentheses. Otherwise, when parsed, NEW will bind to the
632 :         // first viable parentheses (don't traverse into functions).
633 :         if (NodeUtil.containsType(
634 :             first, Token.CALL, NodeUtil.MATCH_NOT_FUNCTION)) {
635 :           precedence = NodeUtil.precedence(first.getType()) + 1;
636 :         }
637 :         addExpr(first, precedence, Context.OTHER);
638 : 
639 :         // '()' is optional when no arguments are present
640 :         Node next = first.getNext();
641 :         if (next != null) {
642 :           add("(");
643 :           addList(next);
644 :           add(")");
645 :         }
646 :         break;
647 : 
648 :       case Token.STRING:
649 :         if (childCount !=
650 :             ((n.getParent() != null &&
651 :               n.getParent().isObjectLit()) ? 1 : 0)) {
652 :           throw new IllegalStateException(
653 :               "Unexpected String children: " + n.getParent().toStringTree());
654 :         }
655 :         addJsString(n);
656 :         break;
657 : 
658 :       case Token.DELPROP:
659 :         Preconditions.checkState(childCount == 1);
660 :         add("delete ");
661 :         add(first);
662 :         break;
663 : 
664 :       case Token.OBJECTLIT: {
665 :         boolean needsParens = (context == Context.START_OF_EXPR);
666 :         if (needsParens) {
667 :           add("(");
668 :         }
669 :         add("{");
670 :         for (Node c = first; c != null; c = c.getNext()) {
671 :           if (c != first) {
672 :             cc.listSeparator();
673 :           }
674 : 
675 :           if (c.isGetterDef() || c.isSetterDef()) {
676 :             add(c);
677 :           } else {
678 :             Preconditions.checkState(c.isString());
679 :             String key = c.getString();
680 :             // Object literal property names don't have to be quoted if they
681 :             // are not JavaScript keywords
682 :             if (!c.isQuotedString() &&
683 :                 !TokenStream.isKeyword(key) &&
684 :                 TokenStream.isJSIdentifier(key) &&
685 :                 // do not encode literally any non-literal characters that
686 :                 // were unicode escaped.
687 :                 NodeUtil.isLatin(key)) {
688 :               add(key);
689 :             } else {
690 :               // Determine if the string is a simple number.
691 :               double d = getSimpleNumber(key);
692 :               if (!Double.isNaN(d)) {
693 :                 cc.addNumber(d);
694 :               } else {
695 :                 addExpr(c, 1, Context.OTHER);
696 :               }
697 :             }
698 :             add(":");
699 :             addExpr(c.getFirstChild(), 1, Context.OTHER);
700 :           }
701 :         }
702 :         add("}");
703 :         if (needsParens) {
704 :           add(")");
705 :         }
706 :         break;
707 :       }
708 : 
709 :       case Token.SWITCH:
710 :         add("switch(");
711 :         add(first);
712 :         add(")");
713 :         cc.beginBlock();
714 :         addAllSiblings(first.getNext());
715 :         cc.endBlock(context == Context.STATEMENT);
716 :         break;
717 : 
718 :       case Token.CASE:
719 :         Preconditions.checkState(childCount == 2);
720 :         add("case ");
721 :         add(first);
722 :         addCaseBody(last);
723 :         break;
724 : 
725 :       case Token.DEFAULT_CASE:
726 :         Preconditions.checkState(childCount == 1);
727 :         add("default");
728 :         addCaseBody(first);
729 :         break;
730 : 
731 :       case Token.LABEL:
732 :         Preconditions.checkState(childCount == 2);
733 :         if (!first.isLabelName()) {
734 :           throw new Error("Unexpected token type. Should be LABEL_NAME.");
735 :         }
736 :         add(first);
737 :         add(":");
738 :         addNonEmptyStatement(
739 :             last, getContextForNonEmptyExpression(context), true);
740 :         break;
741 : 
742 :       default:
743 :         throw new Error("Unknown type " + type + "\n" + n.toStringTree());
744 :     }
745 : 
746 :     cc.endSourceMapping(n);
747 :   }"

